import { useFormik } from "formik";
import React, { useEffect } from "react";
import * as Yup from "yup";
import { useState } from "react";
import useApi from "../../hooks/useApi";
import categoriesApi from "../../api/categoriesApi";
import { useStateContext } from "../../contexts/ContextProvider";
import { ToastContainer, toast } from "react-toastify";
import { AiOutlineLoading } from "react-icons/ai";
import { Button, Input, Textarea } from "@heroui/react";
import { useLocation, useParams } from "react-router-dom";



function CategoryForm(props) {

    const location = useLocation()

    const [item, setitem] = useState(location.state.item ? location.state.item : null)


    useEffect(() => {
        if (location.state.item) {
            setitem(location.state.item)
        }

        console.log('Location at edit', location.state.item)
    }, [])
    useEffect(() => {


        console.log('Item at edit', location.state.item)
    }, [item])



    const { currentColor } = useStateContext();

    const [errors, setErrors] = useState();

    const createCategoyApi = useApi(categoriesApi.categoriesAction);

    const handleCategoryAction = async (data) => {
        await createCategoyApi.request(data);

    }


    const formik = useFormik({
        initialValues: {
            title: item ? item.title : '',
            description: item ? item.description : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action
            setErrors([])

            if (item) {

                handleCategoryAction({
                    "action": "UpdateCategory",
                    "category_details": {
                        "category": item.id,
                        "description": values.description ? values.description : '',
                        "title": values.title,
                        "icon": values.car,
                        "icon_category": values.icon_category
                    }
                })
            } else {
                handleCategoryAction({
                    action: "CreateCategory",
                    category_details: {
                        title: values.title,
                        description: values.description ? values.description : '',
                    },
                })
            }




            resetForm();
        },
    });

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (createCategoyApi.data) {
            if (createCategoyApi.data.errors) {
                setErrors(createCategoyApi.data.errors)
            }
        }

        console.log('createCategoyApi.data', createCategoyApi.data)
    }, [createCategoyApi.data])


    return (
        <div className="h-screen flex items-center justify-center rounded-md shadow-md">
            <ToastContainer position="bottom-center" theme="colored" />
            {createCategoyApi.loading ? (
                <AiOutlineLoading loading={createCategoyApi.loading} />
            ) : (
                <div className="lg:w-5/12 w-full p-3 rounded-md shadow-md col-span-4">
                    <p className="text-center font-bold text-lg">Add new category</p>
                    <form className="items-center grid grid-cols-1"
                        onSubmit={formik.handleSubmit}
                    >
                        <div>
                            
                        </div>

                        <div className="py-2 my-2 max-w-[400px]">
                            <Input
                                className={`${formik.touched.title && formik.errors.title && "is-invalid max-w-[400px]"
                                    }`}
                                id="title"
                                name="title"
                                variant="bordered"
                                placeholder="Title"
                                type="text"
                                onChange={formik.handleChange}
                                onBlur={formik.handleBlur}
                                defaultValue={formik.values.title}
                                value={formik.values.title}
                            />
                            {formik.touched.title && formik.errors.title ? (
                                <p className="text-red-500">{formik.errors.title}</p>
                            ) : null}
                        </div>
                        <div className="py-2 my-2">
                            <Textarea
                                id="description"
                                key="description"
                                name="description"
                                variant="bordered"
                                placeholder="Enter your description"
                                className="col-span-12 md:col-span-6 mb-6 md:mb-0 max-w-[400px]"
                                defaultValue={formik.values.description}
                                value={formik.values.description}
                                onBlur={formik.handleBlur}
                                onChange={formik.handleChange}
                            />

                        </div>

                        <div className="content-center flex-1 justify-center">


                            <Button

                                className="col-span-12 md:col-span-6 mb-6 md:mb-0 min-w-[220px]"
                                size="md"
                                color="primary"
                                type="submit"
                            >
                                Save
                            </Button>
                        </div>
                    </form>
                </div>
            )}
        </div>
    );
}

export default CategoryForm;
